int playOptimal() {
  final random = Random();
  int successCount = 0;
  final boxes = List<int>.generate(100, (i) => i);

  for (int trial = 0; trial < 100000; trial++) {
    boxes.shuffle(random);
    bool allPrisonersSucceeded = true;

    for (int prisoner = 0; prisoner < 100; prisoner++) {
      int currentBox = prisoner;
      bool found = false;

      for (int step = 0; step < 50; step++) {
        currentBox = boxes[currentBox];
        if (currentBox == prisoner) {
          found = true;
          break;
        }
      }

      if (!found) {
        allPrisonersSucceeded = false;
        break;
      }
    }

    if (allPrisonersSucceeded) {
      successCount++;
    }
  }

  double successRate = (successCount * 100.0) / 100000.0;
  return successRate.toInt();  // Truncated integer percentage
}
```

